# -*- coding: utf-8 -*-
"""main-группа: e2e Main-Run по транскрипту плана 2026-10-27 (сценарии MR-1 … MR-8).

E2E проверяет систему целиком: цепочку «пользователь → оркестратор (delegate) → агент (цикл ручек) → answer/escalate
→ оркестратор (answer-user / ask-user / reject)» по журналу прогона и итог для пользователя — правильно ли взаимодействуют
узлы, хватает ли агенту контекста из запроса оркестратора, хватает ли оркестратору ответа агента. Поведение отдельного
узла на фикстурах — в node-isolate (коды сценариев связывают их — SCENARIOS.md). Один тест — один такт: один прогон
до следующего действия пользователя.
"""
from common import test, STAND_M, STAND_K20

P = "main/e2e"

STATE = "`e2e-expected-state` (rule-based по журналу прогона и состоянию стенда): цепочка — тулзы оркестратора и ручки агентов вызваны в ожидаемом порядке и числе, `delegate_to` и обязательные ручки как в эталоне, вопросов пользователю ровно столько, сколько в эталоне, лимиты не превышены [AR-32]; состояние стенда после прогона не изменилось — система только читает [UC-06]."
J_REPORT = "`judge-orch-report` по итоговому тексту пользователю — числа и факты совпадают со сводками ручек в журнале прогона; причины не выдуманы; период или момент данных назван; источники названы понятным языком, имена ручек, команд и классов не названы [UC-22]."
J_READ = "`judge-readability` `[предл.]` — ответ читается без подготовки: не сырой вывод ручек, главное выделено и прокомментировано, длинные перечни свёрнуты в итоги с примерами, объём соразмерен вопросу."
J_Q = "`judge-orch-question` по вопросу пользователю — (1) язык без имён ручек, источников и классов; (2) суть донесена верно"
REFUSAL = "доп. рубрика `judge-orch-refusal` `[предл.]` по тексту отказа — без инструкций и команд для изменений, без имитации выполнения, без имён ручек и без «можно добавить» [UC-25], причина понятна."
LOCALIZE = "Метрики узлов по журналу — для локализации разрыва, в доли node-isolate не входят `[предл.]`: "
NUMBERS = "Фактические числа берутся из журнала прогона (сводки ручек), не из этого описания."
BREAK = "Разрыв цепочки в любом звене — тест не засчитан; где именно он случился, показывают метрики узлов по журналу и парные node-isolate тесты того же кода сценария."
SHORT_CHAIN = "Цепочка короткая — пользователь → оркестратор → пользователь, без агентов. Проверяется, что она действительно короткая: в журнале нет `delegate`, ни одной ручки, на серверах ничего не произошло."
TACT = "Такт один: запрос пользователя → … → терминальная тулза оркестратора; действий пользователя внутри нет."


def e(path, title, scen, stand_extra, inp, chain, behav, ref, metrics, basis, data=None, scenario=None, stand=None):
    test(P + "/" + path, title, [
        ("Сценарий", scen),
        ("Стенд", (stand or STAND_M) + ("\n" + stand_extra if stand_extra else "")),
        ("Вход", inp + " " + TACT if "такт" not in inp.lower() else inp),
        ("Цепочка", chain + "\n\n" + BREAK),
        ("Ожидаемое поведение", behav),
        ("Эталон", ref),
        ("Метрики", metrics),
        ("Основания", basis),
        ("Данные", data or ("Живой стенд M, запрос, эталонная цепочка (адресат, обязательные ручки, число запусков и вопросов), рубрики judge. " + NUMBERS)),
    ], scenario=scenario)


